# -*- coding: utf-8 -*-
import pathlib
def w(path, lines):
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text('\n'.join(lines)+'\n', encoding='utf-8')
    print('OK:', path)
w('docs/operations/LOCAL_DEVELOPMENT.md', ['# LOCAL_DEVELOPMENT.md','','## Prerequis','','- Node.js >= 18','- pnpm >= 8 : npm install -g pnpm','- Git','- Supabase CLI (optionnel, pour DB locale)','','## Installation','','  git clone <repo>','  cd PlateformeVote','  pnpm install','  cp .env.example .env.local','  # Remplir .env.local avec les cles Supabase','  pnpm dev','','## Configuration Supabase (Option cloud gratuit)','','1. Creer un projet sur app.supabase.com','2. Settings > API : recuperer URL et anon key','3. Remplir NEXT_PUBLIC_SUPABASE_URL et NEXT_PUBLIC_SUPABASE_ANON_KEY','4. Remplir SUPABASE_SERVICE_ROLE_KEY (jamais cote client)','','## Multi-tenant en local','','Utiliser un parametre URL ou header controle.','Voir src/middleware.ts pour la configuration.','','## Commandes','','  pnpm dev','  pnpm build','  pnpm lint','  pnpm typecheck','  pnpm test','  pnpm test:e2e','  supabase gen types typescript --local > src/types/database.ts'])
w('docs/operations/BACKUP_RESTORE.md', ['# BACKUP_RESTORE.md','','## Objectifs','','- RPO (perte maximale) : 0 bulletin confirme','- RTO (reprise cible) : moins d une heure','','## Supabase Free - limites','','Pas de sauvegardes automatiques comme le plan Pro.','AUCUNE donnee electorale reelle sur cette offre.','','## Strategie de sauvegarde (production)','','- Sauvegardes automatiques Supabase Pro','- Export periodique via pg_dump','- Stockage chiffre hors site','- Test de restauration mensuel documente','','## Procedure de restauration','','1. Identifier le snapshot cible','2. Creer un environnement propre','3. Restaurer la base','4. Verifier l integrite des donnees','5. Mettre a jour les variables d environnement','6. Tester avant de basculer le trafic','','## Jamais','','- Promettre RPO=0 sur Supabase Free','- Restaurer en production sans test prealable'])
w('docs/operations/runbooks/INCIDENT.md', ['# INCIDENT.md - Runbook incident','','## Detection','','- Monitoring alerte : P0/P1/P2/P3','- Signalement utilisateur','- Detection anomalie interne','','## Isolation','','- Suspendre le scrutin si integrite menacee (decision humaine habilitee)','- Aucune prolongation automatique en cas de panne','- Notifier les parties concernees','','## Evaluation','','- Determiner impact et portee','- Identifier la cause racine','- Estimer le temps de correction','','## Correction','','- Appliquer le correctif','- Verifier en staging','- Deployer','- Confirmer la resolution','','## Post-mortem','','- Documenter dans docs/operations/','- Identifier les ameliorations','- Mettre a jour SECURITY.md si securite','','## Contacts','','A definir lors du passage en production.'])
w('docs/operations/runbooks/ROLLBACK.md', ['# ROLLBACK.md - Runbook rollback','','## Rollback application','','1. Identifier le commit ou tag stable precedent','2. Deployer la version anterieure','3. Verifier que l application repond','4. Verifier les tests de smoke','','## Rollback base de donnees','','Attention : le rollback SQL peut causer une perte de donnees.','1. Evaluer l impact du rollback','2. Sauvegarder l etat actuel','3. Executer la migration inverse','4. Verifier l integrite','','## Cas particulier : scrutin en cours','','Un rollback pendant un scrutin ouvert necessite :','- Decision humaine habilitee','- Analyse d impact sur les bulletins','- Communication aux electeurs','- Audit complet de l operation','','## Jamais','','- Rollback sans sauvegarde prealable','- Rollback SQL d une table bulletins sans procedure electorale'])
w('docs/operations/runbooks/SCRUTIN_INTERRUPTION.md', ['# SCRUTIN_INTERRUPTION.md - Runbook scrutin interrompu','','## Cas declencheurs','','- Panne infrastructure pendant scrutin ouvert','- Detection de fraude ou anomalie','- Decision administrative de suspension','','## Procedure','','1. Suspendre le scrutin (etat paused) - decision humaine habilitee','2. Aucune prolongation automatique : decision motivee, auditee','3. Conserver tous les bulletins deja enregistres','4. Notifier les electeurs sans reveler leur choix','5. Documenter la cause et la duree','6. Decision : reprendre (avec nouvelles dates) ou invalider','7. Si reprise : verifier l integrite avant rouverture','8. Si invalidation : procedure electorale documentee','','## Regles absolues','','- Les bulletins confirmes ne sont jamais supprimes','- La suspension est journalisee avec motif et acteur','- Le super admin ne peut pas modifier les bulletins','- Toute modification exceptionnelle suit une procedure auditee'])
w('docs/compliance/SENEGAL_DATA_PROTECTION_REVIEW.md', ['# SENEGAL_DATA_PROTECTION_REVIEW.md','','## Reference','','Loi n 2008-12 du 25 janvier 2008 relative a la protection des donnees','a caractere personnel (Senegal).','Commission de Protection des Donnees Personnelles (CDP).','','## IMPORTANT : Ce document n est pas un avis juridique','','Faire examiner par une personne competente avant tout traitement reel.','','## Donnees traitees (liste indicative)','','- Identite des membres et administrateurs (nom, email)','- Donnees d electeurs (nom, email, eligibilite)','- Donnees de candidats (nom, biographie, photo)','- Journaux d audit (actions, horodatages)','- Fichiers justificatifs des organisations','','## Formalites CDP potentielles','','- Declaration normale : certains traitements courants','- Demande d autorisation : traitements sensibles ou transferts','','## Points a examiner','','- Finalites du traitement et base juridique','- Minimisation des donnees','- Durees de conservation par categorie','- Droits des personnes (acces, rectification, suppression)','- Sous-traitants (Supabase = hebergeur US)','- Transferts internationaux','- Securite et notification de violation','','## Statut','','A etudier - bloquant avant tout traitement reel.','Ne pas importer de donnees reelles avant cet examen.'])
w('docs/compliance/PROCESSING_REGISTER_TEMPLATE.md', ['# PROCESSING_REGISTER_TEMPLATE.md','','## Modele de registre de traitement','','Remplir pour chaque traitement de donnees personnelles.','','## Traitement : [NOM DU TRAITEMENT]','','Responsable du traitement : [Organisation ou plateforme]','Sous-traitant : [Supabase, Vercel, etc.]','Finalite : [Raison du traitement]','Base juridique : [Consentement / Contrat / Interet legitime / Obligation legale]','Categories de donnees : [Types de donnees]','Destinataires : [Qui accede aux donnees]','Duree de conservation : [Duree + criteres]','Transferts hors Senegal : [Oui/Non + pays + garanties]','Mesures de securite : [RLS, chiffrement, acces restreint]','','## Exemples de traitements a documenter','','1. Gestion des comptes membres et administrateurs','2. Gestion des listes electorales','3. Journaux d audit','4. Communications par email','5. Fichiers justificatifs organisations'])
