w('docs/data-model/DATA_DICTIONARY.md', ['# DATA_DICTIONARY.md','','## Champs communs a toutes les tables metier','','tenant_id : UUID NOT NULL - identifiant de l organisation','id : UUID PRIMARY KEY DEFAULT gen_random_uuid()','created_at : TIMESTAMPTZ DEFAULT now()','updated_at : TIMESTAMPTZ DEFAULT now()','','## Statuts d organisation','','pending | needs_information | approved | active | suspended | disabled | archived | rejected','','## Statuts de demande','','draft | submitted | under_review | needs_information | approved | rejected | provisioning | active','','## Statuts de scrutin','','draft | ready_for_review | approved | scheduled | open | paused | closed | counting','results_under_review | results_provisional | results_final | published | archived','cancelled | invalid_quorum','','## Statuts d electeur','','eligible | ineligible | invited | accepted | voted | abstained','','## Codes de permissions (exemples)','','organization.view | organization.settings.manage | organization.branding.manage','members.view | members.invite | members.roles.manage | members.revoke','elections.view | elections.create | elections.edit_draft | elections.submit_for_review','elections.approve_list | elections.freeze_list | elections.schedule | elections.open','candidates.manage | electorate.import | electorate.validate','results.review | results.validate | results.publish | results.export','audit.view | reports.view | reports.export'])
w('docs/data-model/RETENTION_AND_DELETION.md', ['# RETENTION_AND_DELETION.md','','## Politique de conservation par categorie','','### Comptes et profils','Conservation : duree de la relation + 5 ans (a definir avec conseil)','Suppression : desactivation du compte, puis suppression differee','','### Donnees electorales (resultats publics)','Conservation : permanente (ou selon reglement de l organisation)','Anonymisation : possible apres delai defini','','### Listes electorales','Conservation : duree du scrutin + periode legale contestation','Acces : restreint apres archivage du scrutin','','### Journaux d audit','Conservation : minimum 5 ans (a confirmer selon loi)','Suppression : jamais de suppression sans procedure documentee','','### Fichiers justificatifs','Conservation : duree instruction + 2 ans','Acces : journalise, restreint','Suppression : apres expiration, selon politique organisation','','### Donnees de communication (emails)','Conservation : 1 an (logs) / 3 ans (templates)','','## Droits des personnes','','- Acces : interface dans le backoffice (a implementer)','- Rectification : selon le type de donnee et le contexte electoral','- Suppression : selon retention policy et obligations legales','','## Statut','','A definir et valider avec conseil juridique avant traitement reel.'])
w('docs/product/PRODUCT_OVERVIEW.md', ['# PRODUCT_OVERVIEW.md','','## Vision','','Plateforme SaaS de vote electronique multi-organisations.','Associations, entreprises, universites, syndicats, clubs, federations.','','## Les quatre espaces','','1. Portail public : presentation du service, demande d espace','2. Espace electeur : mobile-first, parcours de vote minimaliste','3. Backoffice organisation : gestion scrutins, membres, communication','4. Backoffice central : supervision, organisations, incidents','','## Cinq roles','','1. Super administrateur de plateforme','2. Administrateur d organisation','3. Gestionnaire electoral','4. Auditeur (lecture seule)','5. Electeur','','## Stack technique','','Next.js App Router + TypeScript strict + Supabase + Tailwind CSS','Voir ADR-0001 et ADR-0002.','','## Contraintes fondamentales','','- Budget initial : 0 FCFA (offres gratuites uniquement)','- Secret du vote : gate absolue avant toute election reelle (ADR-0006)','- Multi-tenant : isolation stricte RLS + tenant_id (ADR-0003)','- Bilingue FR/EN des le lancement (ADR-0005)','- Sandbox uniquement jusqu a audit independant (PRODUCTION_SECURITY_GATE.md)','','## Pour aller plus loin','','Voir docs/product/CAHIER_DES_CHARGES_COMPLET.md'])
w('docs/product/GLOSSARY.md', ['# GLOSSARY.md','','## Tenant','Espace logique d une organisation dans le SaaS.','Identifie par un tenant_id (UUID stable, independant du nom et sous-domaine).','','## RLS (Row Level Security)','Politique d acces aux lignes appliquee directement par PostgreSQL.','Garantit qu un utilisateur ne peut lire que les donnees de son tenant.','','## MFA / TOTP','Authentification multi-facteur par code temporaire (Time-based One-Time Password).','Obligatoire pour les comptes sensibles.','','## RPO (Recovery Point Objective)','Quantite maximale de donnees qu on accepte de perdre apres incident.','Objectif : 0 bulletin confirme perdu.','','## RTO (Recovery Time Objective)','Delai cible pour retablir le service apres incident.','Objectif initial : moins d une heure.','','## Quorum','Seuil de participation requis pour valider un scrutin (si active).','Calcule sur la liste d electeurs eligibles gelee.','','## Bulletin','Expression du vote. Doit etre separe de l identite de l electeur.','','## Sandbox','Environnement de demonstration avec donnees synthetiques.','Marque NON_PRODUCTION. Ne peut pas etre utilise pour une election reelle.','','## ADR (Architecture Decision Record)','Note documentant une decision d architecture : contexte, decision, consequences.','Localisation : docs/architecture/adr/','','## Idempotence','Propriete d une operation qui peut etre repetee sans effet metier duplique.','Essentiel pour les soumissions de bulletins et le provisionnement.','','## Gate de production','Ensemble de conditions obligatoires avant de passer en production reelle.','Voir docs/security/PRODUCTION_SECURITY_GATE.md.'])
w('docs/product/ACCEPTANCE_CRITERIA.md', ['# ACCEPTANCE_CRITERIA.md - Criteres d acceptation transverses','','Source : cahier des charges - section 27.','','## Pour chaque fonctionnalite livree','','- [ ] Criteres d acceptation fonctionnels documentes','- [ ] Validation formulaire cote client ET serveur','- [ ] Controle de permissions cote serveur','- [ ] Controle RLS sur les donnees concernees','- [ ] Tests unitaires des regles metier','- [ ] Tests d integration des transitions et transactions','- [ ] Tests E2E des parcours critiques','- [ ] Tests de refus et d acces interdit','- [ ] Comportement FR/EN complet','- [ ] Etats de chargement, erreur, vide et succes','- [ ] Accessibilite clavier et contraste verifies','- [ ] Journalisation sans donnee sensible superflue','- [ ] Documentation et configuration actualisees','','## Tests sensibles obligatoires','','- Double participation (un electeur ne vote qu une fois)','- Double soumission (idempotence)','- Simultaneite de deux requetes','- Gel de liste (modifications bloquees apres gel)','- Seuil de quorum (calcul correct sur liste gelee)','- Vote blanc (comptage separe, distinct abstention)','- Egalite et regles pre-configurees','- Second tour (scrutin lie, nouvelles regles)','- Visibilite des resultats (controle d acces)','- Suspension et reprise de scrutin','- Publication des resultats (workflow validation)','- Revocation de permission (effet immediat)','- Isolation entre deux tenants (acces refuse)'])
